Item.method_code:
// Innovatorオブジェクト生成
var iomInv = aras.IomInnovator;
// 親Item情報取得
var parentItem = iomInv.newItem(itemTypeName,"get");
parentItem.setID(itemID);
parentItem.setAttribute("select", "managed_by_id,state");
parentItem = parentItem.apply();

// アイテムが取得出来ない場合(新規作成時)は非表示
if(parentItem.getItemCount()<1) return {hidden:true};

// ステートが作業中または改訂中の時以外は非表示
var state = parentItem.getProperty("state", "");
if(state!="InProgress" && state!="InRevision") return {hidden:true};

// 以下標準メソッドcui_ivrcb_deleterow_init
let isDisabled = true;
if (window.computeCorrectControlState) {
  isDisabled = !window.computeCorrectControlState('delete');
}
const tooltip = target.tooltip_template.replace(
  '{0}',
  options.relationshipItemTypeLabel
);
return {
  disabled: isDisabled,
  tooltip_template: tooltip
};
